<?php $title = 'บิล '.$sale->bill_no; $methods = ['cash' => 'เงินสด', 'promptpay' => 'พร้อมเพย์', 'transfer' => 'โอนเงิน', 'card' => 'บัตร']; require __DIR__.'/../layouts/header.php'; ?>
<div class="page-actions no-print"><a href="<?= e(route('sales.index')) ?>">← รายการขาย</a><div class="actions"><a class="button button-secondary" href="<?= e(route('sales.create')) ?>">เปิดบิลใหม่</a><button type="button" data-print>พิมพ์ใบเสร็จ</button></div></div>
<?php require __DIR__.'/../partials/messages.php'; ?>
<section class="card receipt"><div class="receipt-heading"><div><p class="eyebrow">HAIR SALON POS</p><h2>ใบเสร็จรับเงิน</h2><p class="mono"><?= e($sale->bill_no) ?></p></div><span class="badge <?= $sale->status === 'paid' ? 'good' : 'warning' ?>"><?= e(['paid' => 'ชำระแล้ว', 'pending' => 'รอชำระ', 'cancelled' => 'ยกเลิก'][$sale->status]) ?></span></div>
<div class="receipt-info"><p>วันที่ <?= e($sale->created_at?->format('d/m/Y H:i')) ?><br>พนักงาน <?= e($sale->user?->name) ?></p><p>ลูกค้า <?= e($sale->customer?->name ?: 'ลูกค้าทั่วไป') ?><br><?= e($sale->customer?->phone) ?></p></div>
<div class="table-wrap"><table><thead><tr><th>รายการ</th><th>ราคา</th><th>จำนวน</th><th>รวม</th></tr></thead><tbody><?php foreach ($sale->items as $item): ?><tr><td><?= e($item->item_name) ?><?php if ($item->stylist): ?><small>ช่าง: <?= e($item->stylist->name) ?></small><?php endif; ?></td><td><?= e($item->price) ?></td><td><?= e($item->qty) ?></td><td><?= e($item->subtotal) ?></td></tr><?php endforeach; ?></tbody></table></div>
<dl class="totals receipt-totals"><div><dt>ยอดก่อนส่วนลด</dt><dd><?= e($sale->subtotal) ?></dd></div><div><dt>ส่วนลด</dt><dd><?= e($sale->discount) ?></dd></div><div class="grand-total"><dt>ยอดสุทธิ</dt><dd><?= e($sale->total) ?> บาท</dd></div><?php foreach ($sale->payments as $payment): ?><div><dt><?= e($methods[$payment->method]) ?></dt><dd><?= e($payment->amount) ?></dd></div><div><dt>เงินรับ / เงินทอน</dt><dd><?= e($payment->received) ?> / <?= e($payment->change) ?></dd></div><?php if ($payment->ref_no): ?><div><dt>อ้างอิง</dt><dd><?= e($payment->ref_no) ?></dd></div><?php endif; ?><?php endforeach; ?></dl>
<?php if ($sale->status === 'cancelled'): ?><p class="notice error">ยกเลิกเมื่อ <?= e($sale->cancelled_at?->format('d/m/Y H:i')) ?> · <?= e($sale->cancellation_reason) ?></p><?php endif; ?>
<p class="receipt-thanks">ขอบคุณที่ใช้บริการ</p></section>
<?php if ($refunds->isNotEmpty()): ?>
<section class="card no-print"><h2>การคืนเงิน</h2><p class="help">รายการนี้เป็นการบันทึกหลักฐาน พนักงานต้องคืนเงินจริงให้ลูกค้าก่อนยืนยัน</p>
<?php foreach ($refunds as $refund): ?><div class="refund-row"><p><strong><?= e(number_format((float) $refund->amount, 2)) ?> บาท</strong> · <?= $refund->status === 'pending' ? 'รอคืนเงิน' : 'คืนเงินแล้ว' ?></p>
<?php if ($refund->status === 'completed'): ?><p>อ้างอิง <?= e($refund->ref_no) ?> · <?= e($refund->completed_at) ?> · <?= e($refund->completed_by_name) ?></p>
<?php elseif (auth()->user()->hasRole('admin')): ?><form method="post" action="<?= e(route('refunds.complete', $refund->id)) ?>" data-confirm="ยืนยันว่าคืนเงินจริงให้ลูกค้าแล้วหรือไม่?"><?= csrf_field() ?><label for="refund-<?= e($refund->id) ?>">เลขอ้างอิง / หมายเหตุหลักฐาน *</label><input id="refund-<?= e($refund->id) ?>" name="ref_no" required maxlength="255"><button>บันทึกว่าคืนเงินจริงแล้ว</button></form><?php endif; ?></div><?php endforeach; ?></section>
<?php endif; ?>
<?php if (auth()->user()->hasRole('admin') && $sale->status !== 'cancelled'): ?>
<section class="card no-print"><h2>ยกเลิกบิล</h2><p>ระบบจะคืนสต็อกและปรับประวัติสมาชิก พร้อมสร้างรายการรอคืนเงินสำหรับยอดที่รับแล้ว</p><form method="post" action="<?= e(route('sales.cancel', $sale)) ?>" data-confirm="ยืนยันการยกเลิกบิลนี้หรือไม่?"><?= csrf_field() ?><label for="reason">เหตุผล *</label><input id="reason" name="reason" required maxlength="200" value="<?= e(\App\Support\FormValue::old('reason')) ?>"><button class="button-danger">ยกเลิกบิล</button></form></section>
<?php endif; ?>
